import { useEffect, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import {
  ArrowLeft, ArrowRight, ArrowUpRight, CalendarDays, Check, ChevronLeft, ChevronRight,
  CircleHelp, Clock3, Cookie, CreditCard, Download, Edit3, FileText, Layers3, MessageCircle,
  Home, Plus, Search, Settings, SlidersHorizontal, Sparkles, Trash2, Users, Wallet, X,
} from 'lucide-react'
import { closureReasonForDay, monthStart, plainDateLabel, shiftDate, shiftMonth } from './lib/calendar'
import { amountToMinorUnits, formatMoney, normalizePhone, rpc } from './lib/data'
import type {
  Business, ClosureRule, Customer, CustomerBalance, LedgerEntry, Order, OrderPaymentStatus,
  ReminderEvent, Slot,
} from './types/database'
import type { loadBusinessData } from './lib/data'

export type AppPage = 'Today' | 'Calendar' | 'Customers' | 'Customer Detail' | 'Reminders' | 'Settings'
export type BusinessData = Awaited<ReturnType<typeof loadBusinessData>>
export type OrderForm = { customerId: string; serviceDate: string; slotId: string; description: string; quantity: number; amountMinor: number; orderKind: 'regular' | 'bulk'; note: string; allowClosed: boolean }
export type BookingForm = { customerId: string; startsOn: string; weekCount: number; weekdays: number[]; slotId: string; description: string; amountMinor: number; extendForClosures: boolean; advanceMinor: number; advanceMethod: string; advanceDate: string }

type Notice = { kind: 'error' | 'success'; text: string } | null

export function AuthScreen({ configured, notice, busy, onSubmit }: { configured: boolean; notice: Notice; busy: boolean; onSubmit: (event: FormEvent<HTMLFormElement>, email: string) => Promise<boolean> }) {
  const [email, setEmail] = useState('')
  const [sent, setSent] = useState(false)
  return <main className="signin-screen"><div className="signin-art"><div className="art-top"><div className="brand light"><span className="brand-icon"><Cookie size={22}/></span><span><strong>TallyNest</strong></span></div><span className="art-note">A little more ease, every day.</span></div><div className="art-scene"><div className="sun-wash"/><div className="plant plant-one"><i/><i/><i/><b/></div><div className="plant plant-two"><i/><i/><i/><b/></div><div className="jar"><span className="jar-lid"/><span className="jar-label">made with<br/><b>♥</b></span><span className="jar-cookie c1"/><span className="jar-cookie c2"/><span className="jar-cookie c3"/></div><div className="table-line"/></div><div className="art-quote"><span>“</span><p>Good things take time.<br/>We’ll help you keep track.</p><small>YOUR DAY, A LITTLE LIGHTER</small></div><div className="art-bottom"><span>01 / MADE FOR SMALL, LOVELY BUSINESSES</span><span>EST. WITH CARE</span></div></div><section className="signin-panel"><div className="signin-box"><span className="eyebrow">YOUR BUSINESS, IN GOOD HANDS</span><h1>Welcome back.</h1><p className="signin-intro">Sign in to your TallyNest workspace.</p>{!configured && <div className="setup-note"><strong>One small setup step.</strong><span>Add your Supabase project URL and publishable key to <code>.env.local</code> to enable sign-in.</span></div>}{notice && <div className={`notice ${notice.kind}`}>{notice.text}</div>}{sent ? <div className="sent-state"><span className="sent-icon"><Check size={23}/></span><h2>Check your inbox.</h2><p>We sent a sign-in link to <strong>{email}</strong>. Open it on this device to continue.</p><button className="text-button" onClick={() => setSent(false)}>Use a different email</button></div> : <form onSubmit={async event => { if(await onSubmit(event,email))setSent(true) }}><label htmlFor="email">Email address</label><input id="email" type="email" autoComplete="email" placeholder="you@yourbusiness.com" value={email} onChange={event => setEmail(event.target.value)} required disabled={!configured}/><button className="primary-button signin-submit" type="submit" disabled={busy || !configured}>{busy && <span className="spinner"/>} Send me a sign-in link <ArrowUpRight size={17}/></button><p className="signin-footnote"><span className="lock-dot"/> Invite-only access keeps your business data private.</p></form>}<div className="signin-help">Need a hand? Ask your business administrator for an invite.</div></div><span className="signin-copyright">© 2026 TallyNest</span></section></main>
}

export function TodayScreen({ business, data, day, onDayChange, onAddOrder, onAddBooking, onMarkDelivered, onUndoDelivery, onEditOrder, onCancelOrder, onRefresh, onCustomer }: {
  business: Business; data: BusinessData; day: string; onDayChange: (day: string) => void; onAddOrder: () => void; onAddBooking: () => void
  onMarkDelivered: (order: Order) => void; onUndoDelivery: (order: Order) => void; onEditOrder: (order: Order) => void
  onCancelOrder: (order: Order) => void; onRefresh: () => void; onCustomer: (customerId: string) => void
}) {
  const dayOrders = data.orders.filter(order => order.service_date === day && order.status !== 'cancelled')
  const scheduled = dayOrders.filter(order => order.status === 'scheduled')
  const delivered = dayOrders.filter(order => order.status === 'delivered')
  const customerMap = new Map(data.customers.map(customer => [customer.id, customer]))
  const slotGroups = data.slots.filter(slot => slot.is_active).sort((a,b) => a.sort_order-b.sort_order).map(slot => ({ slot, orders: dayOrders.filter(order => order.slot_id === slot.id) }))
  const unassigned = dayOrders.filter(order => !order.slot_id || !data.slots.some(slot => slot.id === order.slot_id && slot.is_active))
  const orderGroups = data.slots.some(slot => slot.is_active) ? [...slotGroups, ...(unassigned.length ? [{ slot: { id: 'unassigned', name: 'No delivery slot', starts_at: null, ends_at: null, sort_order: 999, is_active: true, business_id: business.id }, orders: unassigned }] : [])] : [{ slot: null, orders: dayOrders }]
  const today = todayForZone(business.time_zone)
  return <><div className="page-heading"><div><span className="eyebrow">{plainDateLabel(day).toUpperCase()}</span><h1>{day === today ? 'Today, at a glance' : 'Your order list'}<span className="heading-period">.</span></h1><p>{day === today ? 'A little progress, one lovely order at a time.' : 'Orders scheduled for this date.'}</p></div><div className="heading-actions"><button className="secondary-button" onClick={onAddBooking}><Layers3 size={16}/> Book a week</button><button className="primary-button" onClick={onAddOrder}><Plus size={17}/> Add an order</button></div></div>
    <div className="welcome-strip"><div className="welcome-spark"><Sparkles size={19}/></div><div><strong>{day === today ? 'A fresh day, full of possibility.' : 'A little planning goes a long way.'}</strong><p>Here’s what’s happening in your kitchen.</p></div><label className="day-picker"><CalendarDays size={15}/><input aria-label="Choose day" type="date" value={day} onChange={event => onDayChange(event.target.value)}/></label></div>
    <div className="summary-grid"><SummaryCard label="To prepare" value={String(scheduled.length).padStart(2,'0')} hint="Orders scheduled" icon={Clock3} tone="peach"/><SummaryCard label="Delivered" value={String(delivered.length).padStart(2,'0')} hint="Made someone’s day" icon={Check} tone="sage"/><SummaryCard label="Customers" value={String(data.customers.filter(c=>c.status==='active').length).padStart(2,'0')} hint="In your community" icon={Users} tone="lilac"/></div>
    <section className="content-card today-card"><div className="card-heading"><div><span className="eyebrow">YOUR DAILY RHYTHM</span><h2>{day === today ? 'Today’s orders' : plainDateLabel(day, { day: 'numeric', month: 'long' })}</h2></div><button className="quiet-button" onClick={onRefresh}>Refresh <ChevronRight size={15}/></button></div>{dayOrders.length ? <div className="day-order-groups">{orderGroups.filter(group=>group.orders.length).map(group=><div className="slot-group" key={group.slot?.id ?? 'day'}><div className="slot-group-heading"><strong>{group.slot?.name ?? 'Orders for the day'}</strong><span>{group.orders.length} {group.orders.length===1?'order':'orders'} · {group.orders.filter(o=>o.status==='delivered').length} delivered</span></div>{group.orders.slice().sort((a,b)=>{
          const building=(customerMap.get(a.customer_id)?.building ?? '').localeCompare(customerMap.get(b.customer_id)?.building ?? '')
          return building || a.service_date.localeCompare(b.service_date)
        }).map(order=><OrderRow key={order.id} order={order} customer={customerMap.get(order.customer_id)} currency={business.currency_code} canDeliver={day<=today} onCustomer={()=>onCustomer(order.customer_id)} onMark={()=>onMarkDelivered(order)} onUndo={()=>onUndoDelivery(order)} onEdit={()=>onEditOrder(order)} onCancel={()=>onCancelOrder(order)}/>)}</div>)}</div> : <div className="empty-state"><span className="empty-icon"><Cookie size={22}/></span><strong>Nothing on the list just yet.</strong><p>When orders arrive, you’ll find them here.</p><button className="text-button" onClick={onAddOrder}>Add an order <ArrowUpRight size={15}/></button></div>}</section>
    <div className="bottom-tip"><span>✦</span><p><strong>A tiny tip</strong> — The calendar lets you see booked orders and closures at a glance.</p></div></>
}

function SummaryCard({ label, value, hint, icon: Icon, tone }: { label: string; value: string; hint: string; icon: typeof Home; tone: string }) {
  return <article className="summary-card"><div className={`summary-icon ${tone}`}><Icon size={18} strokeWidth={1.8}/></div><span className="summary-label">{label}</span><strong className="summary-value">{value}</strong><span className="summary-hint">{hint}</span></article>
}

function OrderRow({ order, customer, currency, canDeliver, onCustomer, onMark, onUndo, onEdit, onCancel }: {
  order: Order; customer?: Customer; currency: string; canDeliver: boolean; onCustomer: () => void; onMark: () => void; onUndo: () => void; onEdit: () => void; onCancel: () => void
}) {
  const delivered = order.status === 'delivered'
  const building = [customer?.flat_number, customer?.building].filter(Boolean).join(' · ')
  return <div className={`order-row ${delivered ? 'order-done' : ''}`}><button className={`order-state ${delivered?'complete':''}`} aria-label={delivered?'Undo delivery':'Mark delivered'} onClick={delivered?onUndo:canDeliver?onMark:undefined} disabled={!delivered&&!canDeliver}>{delivered?<Check size={15}/>:<span/>}</button><button className="order-person order-person-button" onClick={onCustomer}><strong>{customer?.full_name??'Customer'}</strong><small>{[building,order.description|| (order.order_kind==='bulk'?'Bulk order':'Regular order')].filter(Boolean).join(' · ')}</small></button>{order.order_kind==='bulk'&&<span className="bulk-pill">BULK</span>}<span className="order-amount">{formatMoney(order.amount_minor,currency)}</span>{delivered?<button className="status-pill delivered" onClick={onUndo}>Delivered · undo</button>:canDeliver?<button className="deliver-button" onClick={onMark}>Mark delivered</button>:<span className="status-pill scheduled">Scheduled</span>}{!delivered&&<div className="row-more"><button className="icon-button" aria-label="Edit order" onClick={onEdit}><Edit3 size={15}/></button><button className="icon-button" aria-label="Cancel order" onClick={()=>{if(window.confirm('Cancel this scheduled order? It will stay in history and will not count as owed.'))onCancel()}}><X size={16}/></button></div>}</div>
}

function todayForZone(timeZone:string){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return `${parts.find(p=>p.type==='year')?.value}-${parts.find(p=>p.type==='month')?.value}-${parts.find(p=>p.type==='day')?.value}`}

function ModalFrame({children,onClose,title}:{children:ReactNode;onClose:()=>void;title:string}){
  return <div className="modal-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="customer-modal workflow-modal" role="dialog" aria-modal="true" aria-label={title}><button className="icon-button modal-close" onClick={onClose} aria-label="Close"><X size={18}/></button>{children}</section></div>
}

export function CustomerDialog({customer,customers,business,busy,onClose,onSave}:{customer:Customer|null;customers:Customer[];business:Business;busy:boolean;onClose:()=>void;onSave:(values:{id?:string;fullName:string;phone:string|null;flat:string|null;building:string|null;address:string|null;note:string|null;status:'active'|'archived'})=>Promise<void>}){
  const [fullName,setFullName]=useState(customer?.full_name??'')
  const [phone,setPhone]=useState(customer?.phone_e164??'')
  const [flat,setFlat]=useState(customer?.flat_number??'')
  const [building,setBuilding]=useState(customer?.building??'')
  const [address,setAddress]=useState(customer?.address_text??'')
  const [note,setNote]=useState('')
  const status=customer?.status??'active'
  const normalized=normalizePhone(phone,business.country_code)
  const duplicate=customers.find(item=>item.id!==customer?.id&&((normalized&&item.phone_e164===normalized)||(fullName.trim().length>3&&item.full_name.toLowerCase().includes(fullName.trim().toLowerCase()))))
  async function submit(event:FormEvent){event.preventDefault();await onSave({id:customer?.id,fullName:fullName.trim(),phone:normalized,flat:flat.trim()||null,building:building.trim()||null,address:address.trim()||null,note:note.trim()||null,status})}
  return <ModalFrame title={customer?'Edit customer':'Add customer'} onClose={()=>{if(!busy)onClose()}}><span className="eyebrow">{customer?'KEEP DETAILS UP TO DATE':'A NEW FACE IN YOUR COMMUNITY'}</span><h2 id="customer-modal-title">{customer?'Edit customer':'Add a customer'}</h2><p>Keep the details you’ll want close at hand.</p><form className="workflow-form" onSubmit={submit}><label>Full name<input required autoFocus maxLength={160} value={fullName} onChange={e=>setFullName(e.target.value)} placeholder="e.g. Ananya Sharma"/></label><label>Phone number<input type="tel" value={phone} onChange={e=>setPhone(e.target.value)} placeholder={`+${business.country_code} 98765 43210`}/><small>We’ll add +{business.country_code} when you enter a local number.</small></label>{duplicate&&<div className="duplicate-warning"><CircleHelp size={15}/><span>This may already be saved as <strong>{duplicate.full_name}</strong>{duplicate.phone_e164?` (${duplicate.phone_e164})`:''}. Check before adding a second record.</span></div>}<div className="form-two-col"><label>Flat / unit<input maxLength={80} value={flat} onChange={e=>setFlat(e.target.value)} placeholder="Flat 4B"/></label><label>Building<input maxLength={120} value={building} onChange={e=>setBuilding(e.target.value)} placeholder="Rosewood Apartments"/></label></div><label>Other address details<textarea rows={2} maxLength={500} value={address} onChange={e=>setAddress(e.target.value)} placeholder="Street, area, landmark, pincode…"/></label>{!customer&&<label>Notes for the kitchen<textarea rows={2} maxLength={4000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Delivery details or preferences…"/></label>}<div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary-button" type="submit" disabled={busy||!fullName.trim()}>{busy?<span className="spinner"/>:<Plus size={16}/>} {customer?'Save details':'Save customer'}</button></div></form></ModalFrame>
}

export function OrderDialog({order,customers,slots,closures,business,selectedCustomerId,selectedDay,busy,onClose,onSave,onAddCustomer}:{order:Order|null;customers:Customer[];slots:Slot[];closures:ClosureRule[];business:Business;selectedCustomerId:string|null;selectedDay:string;busy:boolean;onClose:()=>void;onSave:(values:OrderForm)=>Promise<void>;onAddCustomer:()=>void}){
  const isEdit=Boolean(order?.id)
  const today=todayForZone(business.time_zone)
  const maxDate=shiftDate(today,30)
  const [customerId,setCustomerId]=useState(order?.customer_id??selectedCustomerId??'')
  useEffect(()=>{if(!order?.id&&selectedCustomerId)setCustomerId(selectedCustomerId)},[selectedCustomerId,order?.id])
  const [serviceDate,setServiceDate]=useState(order?.service_date??selectedDay)
  const [slotId,setSlotId]=useState(order?.slot_id??'')
  const [description,setDescription]=useState(order?.description??'')
  const [quantity,setQuantity]=useState(String(order?.quantity??1))
  const [amount,setAmount]=useState(order?String((order.amount_minor/100).toFixed(2)):'')
  const [orderKind,setOrderKind]=useState<'regular'|'bulk'>(order?.order_kind??'regular')
  const [note,setNote]=useState(order?.note??'')
  const [allowClosed,setAllowClosed]=useState(false)
  const [customerSearch,setCustomerSearch]=useState('')
  const closure=closureReasonForDay(closures,serviceDate,slotId||null)
  const matches=customers.filter(c=>[c.full_name,c.phone_e164,c.flat_number,c.building].some(value=>value?.toLowerCase().includes(customerSearch.toLowerCase())))
  async function submit(event:FormEvent){event.preventDefault();try{await onSave({customerId,serviceDate,slotId,description:description.trim(),quantity:Number(quantity),amountMinor:amountToMinorUnits(amount),orderKind,note:note.trim(),allowClosed})}catch{}}
  return <ModalFrame title={isEdit?'Edit order':'Add an order'} onClose={()=>{if(!busy)onClose()}}><span className="eyebrow">{orderKind==='bulk'?'PLAN AHEAD':'A DELIVERY, ALL WRITTEN DOWN'}</span><h2>{isEdit?'Edit scheduled order':order?.id?'Repeat order':'Add an order'}</h2><p>Amounts stay on this order, even when your prices change later.</p><form className="workflow-form" onSubmit={submit}><label>Customer<div className="inline-select"><select required value={customerId} onChange={e=>setCustomerId(e.target.value)}><option value="">Choose a customer</option>{customers.map(c=><option value={c.id} key={c.id}>{c.full_name}{c.phone_e164?` · ${c.phone_e164}`:''}</option>)}</select><button className="icon-button" type="button" aria-label="Add customer" onClick={onAddCustomer}><Plus size={17}/></button></div></label>{customers.length>6&&<label>Search customer<input value={customerSearch} onChange={e=>setCustomerSearch(e.target.value)} placeholder="Name, phone, flat or building"/><small>{matches.slice(0,3).map(c=>c.full_name).join(' · ')||'No matches'}</small></label>}<div className="form-two-col"><label>Service date<input type="date" required value={serviceDate} max={maxDate} onChange={e=>setServiceDate(e.target.value)}/></label><label>Delivery slot<select value={slotId} onChange={e=>setSlotId(e.target.value)}><option value="">No slot</option>{slots.map(slot=><option value={slot.id} key={slot.id}>{slot.name}{slot.starts_at?` · ${slot.starts_at.slice(0,5)}`:''}</option>)}</select></label></div><label>Description<input maxLength={500} value={description} onChange={e=>setDescription(e.target.value)} placeholder="e.g. Combo 1 lunch"/></label><div className="form-two-col"><label>Quantity<input type="number" required min="0.001" step="0.001" value={quantity} onChange={e=>setQuantity(e.target.value)}/></label><label>Amount ({business.currency_code})<input type="number" required min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label></div><div className="radio-row"><label><input type="radio" checked={orderKind==='regular'} onChange={()=>setOrderKind('regular')}/> Regular order</label><label><input type="radio" checked={orderKind==='bulk'} onChange={()=>setOrderKind('bulk')}/> Bulk or event order</label></div>{orderKind==='bulk'&&<div className="bulk-note"><Layers3 size={15}/> This order will be highlighted as a bulk order in the calendar. You can tag a deposit to it from the customer’s payment form.</div>}<label>Order note<textarea rows={2} maxLength={2000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Address, occasion or delivery note…"/></label>{closure&&<div className="closure-warning"><strong>This delivery slot is closed.</strong><span>{closure}. You can still add an order after reviewing this warning.</span><label><input type="checkbox" checked={allowClosed} onChange={e=>setAllowClosed(e.target.checked)}/> Add it anyway</label></div>}<div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary-button" type="submit" disabled={busy||!customerId||Boolean(closure&&!allowClosed)}>{busy?<span className="spinner"/>:<Plus size={16}/>} {isEdit?'Save order':'Add order'}</button></div>{!customers.length&&<button className="text-button" type="button" onClick={onAddCustomer}>Add a customer first <ArrowUpRight size={14}/></button>}</form></ModalFrame>
}

export function BookingDialog({customers,slots,business,selectedCustomerId,selectedDay,busy,onClose,onSave}:{customers:Customer[];slots:Slot[];business:Business;selectedCustomerId:string|null;selectedDay:string;busy:boolean;onClose:()=>void;onSave:(values:BookingForm)=>Promise<void>}){
  const [customerId,setCustomerId]=useState(selectedCustomerId??'')
  const [startsOn,setStartsOn]=useState(selectedDay)
  const [weeks,setWeeks]=useState('1')
  const [weekdays,setWeekdays]=useState([1,2,3,4,5])
  const [slotId,setSlotId]=useState('')
  const [description,setDescription]=useState('')
  const [amount,setAmount]=useState('')
  const [extend,setExtend]=useState(false)
  const [advance,setAdvance]=useState('')
  const [advanceMethod,setAdvanceMethod]=useState('upi')
  const [preview,setPreview]=useState<Record<string,any>|null>(null)
  const [previewBusy,setPreviewBusy]=useState(false)
  const [error,setError]=useState('')
  function toggle(day:number){setWeekdays(current=>current.includes(day)?current.filter(value=>value!==day):[...current,day].sort((a,b)=>a-b));setPreview(null)}
  async function getPreview(){setError('');setPreviewBusy(true);try{const result=await rpc<Record<string,any>>('preview_week_booking',{p_business_id:business.id,p_customer_id:customerId,p_starts_on:startsOn,p_week_count:Number(weeks),p_weekdays:weekdays,p_slot_id:slotId||null,p_extend_for_closures:extend});setPreview(result)}catch(e){setError(e instanceof Error?e.message:'Could not preview these dates.')}finally{setPreviewBusy(false)}}
  async function submit(event:FormEvent){event.preventDefault();if(!preview){await getPreview();return}try{await onSave({customerId,startsOn,weekCount:Number(weeks),weekdays,slotId,description:description.trim(),amountMinor:amountToMinorUnits(amount),extendForClosures:extend,advanceMinor:advance?Math.round(Number(advance)*100):0,advanceMethod:advance?advanceMethod:'',advanceDate:todayForZone(business.time_zone)})}catch{}}
  const previews=Array.isArray(preview?.dates)?preview.dates as Array<{service_date:string;is_closed:boolean;closure_reason:string|null;will_create:boolean}>:[]
  return <ModalFrame title="Book a week" onClose={()=>{if(!busy)onClose()}}><span className="eyebrow">ONE STEP, A WEEK OF ORDERS</span><h2>Book a week</h2><p>Preview each delivery date before orders are created.</p><form className="workflow-form" onSubmit={submit}><label>Customer<select required value={customerId} onChange={e=>{setCustomerId(e.target.value);setPreview(null)}}><option value="">Choose a customer</option>{customers.map(c=><option value={c.id} key={c.id}>{c.full_name}</option>)}</select></label><div className="form-two-col"><label>Start date<input type="date" required value={startsOn} onChange={e=>{setStartsOn(e.target.value);setPreview(null)}}/></label><label>Number of weeks<input type="number" required min="1" max="52" value={weeks} onChange={e=>{setWeeks(e.target.value);setPreview(null)}}/></label></div><fieldset className="weekday-picker"><legend>Delivery days</legend>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((label,day)=><label key={label} className={weekdays.includes(day)?'checked':''}><input type="checkbox" checked={weekdays.includes(day)} onChange={()=>toggle(day)}/>{label}</label>)}</fieldset><label>Delivery slot<select value={slotId} onChange={e=>{setSlotId(e.target.value);setPreview(null)}}><option value="">No slot</option>{slots.map(slot=><option key={slot.id} value={slot.id}>{slot.name}</option>)}</select></label><label>Description<input value={description} maxLength={500} onChange={e=>setDescription(e.target.value)} placeholder="e.g. Lunch combo"/></label><div className="form-two-col"><label>Amount per delivery ({business.currency_code})<input type="number" min="0.01" step="0.01" required value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label><label>Advance payment (optional)<input type="number" min="0" step="0.01" value={advance} onChange={e=>setAdvance(e.target.value)} placeholder="0.00"/></label></div>{Number(advance)>0&&<label>Advance payment method<select value={advanceMethod} onChange={e=>setAdvanceMethod(e.target.value)}><option value="cash">Cash</option><option value="upi">UPI</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select></label>}<label className="checkline"><input type="checkbox" checked={extend} onChange={e=>{setExtend(e.target.checked);setPreview(null)}}/> Extend the booking to make up delivery days skipped for closures</label><button className="secondary-button preview-button" type="button" disabled={!customerId||!weekdays.length||previewBusy} onClick={()=>void getPreview()}><CalendarDays size={15}/>{previewBusy?'Checking dates…':'Preview dates'}</button>{error&&<div className="notice error">{error}</div>}{preview&&<div className="booking-preview"><div className="preview-summary"><strong>{preview.order_count} orders</strong><span>{preview.skipped_count} skipped for closures</span></div><div className="preview-dates">{previews.map(item=><div key={item.service_date} className={item.is_closed?'skip':''}><span>{plainDateLabel(item.service_date,{weekday:'short',day:'numeric',month:'short'})}</span><span>{item.will_create?'Will create':item.closure_reason||'Closed'}</span></div>)}</div></div>}<div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary-button" type="submit" disabled={busy||!customerId||!weekdays.length||!preview||preview.order_count===0}>{busy?<span className="spinner"/>:null} Confirm booking</button></div></form></ModalFrame>
}

export function PaymentDialog({kind,customers,orders,business,initialCustomerId,initialOrderId,busy,onClose,onSave}:{kind:'received'|'returned';customers:Customer[];orders:Order[];business:Business;initialCustomerId:string|null;initialOrderId:string|null;busy:boolean;onClose:()=>void;onSave:(values:{customerId:string;amountMinor:number;date:string;method:string|null;note:string;taggedOrderId:string|null;kind:'received'|'returned'})=>Promise<void>}){
  const [customerId,setCustomerId]=useState(initialCustomerId??'')
  const [amount,setAmount]=useState('')
  const [date,setDate]=useState(todayForZone(business.time_zone))
  const [method,setMethod]=useState('cash')
  const [note,setNote]=useState('')
  const [tag,setTag]=useState(initialOrderId??'')
  const customersOrders=orders.filter(order=>order.customer_id===customerId&&order.status!=='cancelled')
  async function submit(event:FormEvent){event.preventDefault();try{await onSave({customerId,amountMinor:amountToMinorUnits(amount),date,method:kind==='received'?method:null,note:note.trim(),taggedOrderId:tag||null,kind})}catch{}}
  return <ModalFrame title={kind==='received'?'Record payment':'Record return'} onClose={()=>{if(!busy)onClose()}}><span className="eyebrow">{kind==='received'?'MONEY RECEIVED':'MONEY RETURNED'}</span><h2>{kind==='received'?'Record a payment':'Record a return'}</h2><p>{kind==='received'?'Partial payments and advances both work.':'A returned amount increases what is owed, as shown in the ledger.'}</p><form className="workflow-form" onSubmit={submit}><label>Customer<select required value={customerId} onChange={e=>{setCustomerId(e.target.value);setTag('')}}><option value="">Choose a customer</option>{customers.map(c=><option value={c.id} key={c.id}>{c.full_name}</option>)}</select></label><div className="form-two-col"><label>Amount ({business.currency_code})<input type="number" required min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label><label>Date<input type="date" required value={date} onChange={e=>setDate(e.target.value)}/></label></div>{kind==='received'&&<label>Payment method<select value={method} onChange={e=>setMethod(e.target.value)}><option value="cash">Cash</option><option value="upi">UPI</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select></label>}<label>{kind==='received'?'Tag this payment to an order (optional)':'Tag this return to an order (optional)'}<select value={tag} onChange={e=>setTag(e.target.value)}><option value="">General {kind==='received'?'payment':'return'}</option>{customersOrders.map(order=><option value={order.id} key={order.id}>{plainDateLabel(order.service_date,{day:'numeric',month:'short'})} · {order.description||'Order'} · {formatMoney(order.amount_minor,business.currency_code)}</option>)}</select><small>A tagged deposit stays with its order; a general payment pays the oldest unpaid delivery first.</small></label><label>Note<input maxLength={1000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Optional reference or detail"/></label><div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary-button" type="submit" disabled={busy||!customerId}>{busy?<span className="spinner"/>:<Wallet size={16}/>} Record {kind==='received'?'payment':'return'}</button></div></form></ModalFrame>
}

export function ClosureDialog({business,slots,orders,customers,closures,busy,onClose,onSave}:{business:Business;slots:Slot[];orders:Order[];customers:Map<string,Customer>;closures:ClosureRule[];busy:boolean;onClose:()=>void;onSave:(values:{id?:string;rule:Record<string,string|number|null>})=>Promise<void>}){
  const [type,setType]=useState<ClosureRule['rule_type']>('date_range')
  const [action,setAction]=useState<ClosureRule['action']>('closed')
  const [start,setStart]=useState(todayForZone(business.time_zone))
  const [end,setEnd]=useState(todayForZone(business.time_zone))
  const [slotId,setSlotId]=useState('')
  const [weekday,setWeekday]=useState('0')
  const [monthDay,setMonthDay]=useState('1')
  const [weekOfMonth,setWeekOfMonth]=useState('1')
  const [reason,setReason]=useState('')
  const candidate:ClosureRule={id:'preview',business_id:business.id,slot_id:slotId||null,rule_type:action==='open_exception'?'exception':type,starts_on:start||null,ends_on:action==='open_exception'?start||null:end||null,weekday:type==='weekday'||type==='monthly_weekday'?Number(weekday):null,month_day:type==='monthly_date'?Number(monthDay):null,week_of_month:type==='monthly_weekday'?Number(weekOfMonth):null,action,reason:reason||null}
  const conflicts=orders.filter(order=>order.status==='scheduled'&&closureReasonForDay([...closures,candidate],order.service_date,order.slot_id)).sort((a,b)=>a.service_date.localeCompare(b.service_date))
  async function submit(event:FormEvent){event.preventDefault();const rule={slot_id:slotId||null,rule_type:action==='open_exception'?'exception':type,starts_on:start||null,ends_on:action==='open_exception'?start||null:end||null,weekday:type==='weekday'||type==='monthly_weekday'?Number(weekday):null,month_day:type==='monthly_date'?Number(monthDay):null,week_of_month:type==='monthly_weekday'?Number(weekOfMonth):null,action,reason:reason.trim()||null};try{await onSave({rule})}catch{}}
  return <ModalFrame title="Add a closure" onClose={()=>{if(!busy)onClose()}}><span className="eyebrow">PLAN FOR A DAY OFF</span><h2>{action==='open_exception'?'Add an open exception':'Add a closure'}</h2><p>Existing orders stay in place. Review conflicts before saving.</p><form className="workflow-form" onSubmit={submit}><label>Rule type<select value={action==='open_exception'?'exception':type} onChange={e=>{const value=e.target.value;if(value==='exception'){setAction('open_exception')}else{setAction('closed');setType(value as ClosureRule['rule_type']);setEnd(value==='date_range'||value==='daily'?start:'')}}}><option value="date_range">One-off date or range</option><option value="daily">Daily within a date range</option><option value="weekday">Every week on a weekday</option><option value="monthly_date">Monthly by date</option><option value="monthly_weekday">Monthly by weekday</option><option value="exception">Open exception on one date</option></select></label><div className="form-two-col"><label>{action==='open_exception'?'Open date':'Starts on'}<input type="date" required value={start} onChange={e=>setStart(e.target.value)}/></label>{action!=='open_exception'&&<label>{type==='date_range'||type==='daily'?'Ends on':'Ends recurrence on (optional)'}<input type="date" value={end} min={start} onChange={e=>setEnd(e.target.value)}/></label>}</div>{(type==='weekday'||type==='monthly_weekday')&&action==='closed'&&<label>Weekday<select value={weekday} onChange={e=>setWeekday(e.target.value)}>{['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((day,index)=><option key={day} value={index}>{day}</option>)}</select></label>}{type==='monthly_date'&&action==='closed'&&<label>Day of month<select value={monthDay} onChange={e=>setMonthDay(e.target.value)}>{Array.from({length:31},(_,i)=><option key={i} value={i+1}>{i+1}</option>)}</select></label>}{type==='monthly_weekday'&&action==='closed'&&<label>Occurrence<select value={weekOfMonth} onChange={e=>setWeekOfMonth(e.target.value)}><option value="1">First</option><option value="2">Second</option><option value="3">Third</option><option value="4">Fourth</option><option value="-1">Last</option></select></label>}<label>Delivery slot<select value={slotId} onChange={e=>setSlotId(e.target.value)}><option value="">All slots</option>{slots.map(slot=><option key={slot.id} value={slot.id}>{slot.name}</option>)}</select></label><label>Reason (optional)<input maxLength={500} value={reason} onChange={e=>setReason(e.target.value)} placeholder="e.g. Sunday evening break"/></label>{conflicts.length>0&&action==='closed'&&<div className="conflict-box"><strong>{conflicts.length} scheduled order{conflicts.length===1?'':'s'} overlap this closure.</strong><p>They will not be deleted or changed. Review the day and reschedule or cancel each order if needed.</p><div className="conflict-list">{conflicts.slice(0,8).map(order=><span key={order.id}>{plainDateLabel(order.service_date,{day:'numeric',month:'short'})} · {customers.get(order.customer_id)?.full_name??'Customer'}{order.slot_id?` · ${slots.find(s=>s.id===order.slot_id)?.name??''}`:''}</span>)}</div>{conflicts.length>8&&<small>And {conflicts.length-8} more scheduled orders.</small>}</div>}{action==='open_exception'&&<div className="bulk-note"><Sparkles size={15}/> This exception opens the selected date even if a matching weekly or date-range closure applies.</div>}<div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button><button className="primary-button" type="submit" disabled={busy||!start||((type==='date_range'||type==='daily')&&!end)}>{busy?<span className="spinner"/>:<Plus size={16}/>} Save closure</button></div></form></ModalFrame>
}

export function CalendarScreen({ business, data, onSelectDay, onAddOrder, onAddBooking }: { business:Business;data:BusinessData;onSelectDay:(day:string)=>void;onAddOrder:()=>void;onAddBooking:()=>void }) {
  const today=todayForZone(business.time_zone)
  const [month,setMonth]=useState(monthStart(today))
  const [view,setView]=useState<'month'|'week'>('month')
  const [weekStart,setWeekStart]=useState(()=>{const d=new Date(`${today}T00:00:00Z`);return shiftDate(today,-((d.getUTCDay()+6)%7))})
  const monthKey=`${month.getUTCFullYear()}-${String(month.getUTCMonth()+1).padStart(2,'0')}`
  const monthLabel=new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric',timeZone:'UTC'}).format(month)
  const totalDays=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate()
  const lead=(new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth(),1)).getUTCDay()+6)%7
  const days=Array.from({length:totalDays},(_,i)=>`${monthKey}-${String(i+1).padStart(2,'0')}`)
  const weekDays=Array.from({length:7},(_,i)=>shiftDate(weekStart,i))
  const countOn=(date:string)=>data.orders.filter(order=>order.service_date===date&&order.status!=='cancelled').length
  const bulkOn=(date:string)=>data.orders.filter(order=>order.service_date===date&&order.status!=='cancelled'&&order.order_kind==='bulk').length
  return <><div className="page-heading"><div><span className="eyebrow">A LITTLE PLAN GOES A LONG WAY</span><h1>Your calendar<span className="heading-period">.</span></h1><p>Plan the day, week or month ahead.</p></div><div className="heading-actions"><button className="secondary-button" onClick={onAddBooking}><Layers3 size={16}/> Book a week</button><button className="primary-button" onClick={onAddOrder}><Plus size={17}/> Add an order</button></div></div><div className="calendar-layout"><section className="content-card calendar-card"><div className="calendar-controls"><div><span className="eyebrow">YOUR {view==='month'?'MONTH':'WEEK'}</span><h2>{view==='month'?monthLabel:`${plainDateLabel(weekStart,{day:'numeric',month:'short'})} – ${plainDateLabel(weekDays[6],{day:'numeric',month:'long',year:'numeric'})}`}</h2></div><div className="calendar-actions"><div className="view-switch"><button className={view==='month'?'selected':''} onClick={()=>setView('month')}>Month</button><button className={view==='week'?'selected':''} onClick={()=>setView('week')}>Week</button></div><div className="calendar-arrows"><button className="icon-button" aria-label="Previous period" onClick={()=>view==='month'?setMonth(monthStart(shiftMonth(`${monthKey}-01`,-1))):setWeekStart(shiftDate(weekStart,-7))}><ChevronLeft size={18}/></button><button className="icon-button" aria-label="Next period" onClick={()=>view==='month'?setMonth(monthStart(shiftMonth(`${monthKey}-01`,1))):setWeekStart(shiftDate(weekStart,7))}><ChevronRight size={18}/></button></div></div></div>{view==='month'?<div className="calendar-grid"><div className="weekday-row">{['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=><span key={d}>{d}</span>)}</div><div className="dates-grid">{Array.from({length:lead},(_,i)=><span className="date-cell blank" key={`blank-${i}`}/>)}{days.map(day=><CalendarDay key={day} day={day} today={today} count={countOn(day)} bulkCount={bulkOn(day)} rules={data.closures} slots={data.slots} onClick={()=>onSelectDay(day)}/>)}</div></div>:<div className="week-calendar">{weekDays.map(day=><CalendarDay key={day} day={day} today={today} count={countOn(day)} bulkCount={bulkOn(day)} rules={data.closures} slots={data.slots} onClick={()=>onSelectDay(day)} week/>)}</div>}<div className="calendar-legend"><span><i className="legend-order"/> Has orders</span><span><i className="legend-closed"/> Closed slot/day</span><span><i className="legend-bulk"/> Bulk order</span></div></section><aside className="content-card calendar-aside"><span className="eyebrow">A NOTE FOR TODAY</span><span className="calendar-flower">✿</span><h2>{plainDateLabel(today,{day:'numeric',month:'long'})}</h2><p>{countOn(today)?`${countOn(today)} order${countOn(today)===1?'':'s'} are on the list today.`:'No orders on the calendar today. There’s room for something lovely.'}</p><button className="text-button" onClick={()=>onSelectDay(today)}>Open today’s list <ArrowRight size={15}/></button><div className="calendar-aside-divider"/><strong className="aside-subtitle">Coming up</strong>{data.orders.filter(o=>o.status==='scheduled'&&o.service_date>today).sort((a,b)=>a.service_date.localeCompare(b.service_date)).slice(0,4).map(order=><button className="upcoming-mini" key={order.id} onClick={()=>onSelectDay(order.service_date)}><span>{plainDateLabel(order.service_date,{day:'numeric',month:'short'})}</span><span>{data.customers.find(c=>c.id===order.customer_id)?.full_name??'Customer'}</span><ChevronRight size={14}/></button>)}</aside></div></>
}

function CalendarDay({day,today,count,bulkCount,rules,slots,onClick,week=false}:{day:string;today:string;count:number;bulkCount:number;rules:ClosureRule[];slots:Slot[];onClick:()=>void;week?:boolean}){
  const closure=slots.length?slots.some(slot=>slot.is_active&&closureReasonForDay(rules,day,slot.id)):Boolean(closureReasonForDay(rules,day,null))
  return <button className={`date-cell ${day===today?'is-today':''} ${week?'week-cell':''} ${closure?'has-closure':''}`} onClick={onClick}><span className="date-day">{Number(day.slice(-2))}</span>{count>0&&<span className="date-order-count">{count} {count===1?'order':'orders'}</span>}{bulkCount>0&&<span className="bulk-calendar-pill">Bulk</span>}{closure&&<span className="closure-indicator">Closed</span>}</button>
}

export function CustomerScreen({data,filtered,query,onQuery,onAdd,onOpen,onExport}:{data:BusinessData;filtered:Customer[];query:string;onQuery:(value:string)=>void;onAdd:()=>void;onOpen:(id:string)=>void;onExport:()=>void}){
  const [status,setStatus]=useState<'active'|'archived'>('active')
  const rows=status==='active'?filtered:data.customers.filter(customer=>customer.status===status&&(!query.trim()||[customer.full_name,customer.phone_e164,customer.flat_number,customer.building,customer.address_text].some(value=>value?.toLowerCase().includes(query.toLowerCase()))))
  const balanceMap=new Map(data.balances.map(balance=>[balance.customer_id,balance]))
  return <><div className="page-heading"><div><span className="eyebrow">PEOPLE MAKE THE GOOD THINGS</span><h1>Your customers<span className="heading-period">.</span></h1><p>Customer details, balances and booked orders in one place.</p></div><div className="heading-actions"><button className="secondary-button" onClick={onExport}><Download size={16}/> Export CSV</button><button className="primary-button" onClick={onAdd}><Plus size={17}/> Add a customer</button></div></div><section className="content-card customer-card"><div className="customer-toolbar"><div className="search-box"><Search size={17}/><input value={query} onChange={e=>onQuery(e.target.value)} placeholder="Find by name, phone, flat or building" aria-label="Search customers"/></div><div className="view-switch"><button className={status==='active'?'selected':''} onClick={()=>setStatus('active')}>Active</button><button className={status==='archived'?'selected':''} onClick={()=>setStatus('archived')}>Archived</button></div></div>{rows.length?<div className="customer-table"><div className="customer-table-head customer-table-full"><span>CUSTOMER</span><span>PHONE</span><span>ADDRESS</span><span>BOOKED AHEAD</span><span>TOTAL OWED</span></div>{rows.map(customer=>{const balance=balanceMap.get(customer.id);return <button className="customer-table-row customer-table-full" key={customer.id} onClick={()=>onOpen(customer.id)}><span className="customer-cell"><span className="customer-avatar">{initials(customer.full_name)}</span><strong>{customer.full_name}</strong></span><span>{customer.phone_e164||'—'}</span><span>{[customer.flat_number,customer.building,customer.address_text].filter(Boolean).join(', ')||'—'}</span><span>{balance?.booked_order_count??0} orders</span><span className={`balance-text ${(balance?.total_owed_minor??0)<0?'credit':''}`}>{formatMoney(balance?.total_owed_minor??0)}</span></button>})}</div>:<div className="empty-state"><span className="empty-icon"><Users size={21}/></span><strong>{query?'No one by that name yet.':status==='active'?'Your community starts here.':'No archived customers.'}</strong><p>{query?'Try another name, phone number or address.':'Add a customer and keep their details close at hand.'}</p>{status==='active'&&!query&&<button className="text-button" onClick={onAdd}>Add your first customer <ArrowUpRight size={15}/></button>}</div>}</section></>
}

export function CustomerDetailScreen({business,customer,balance,orders,entries,notes,slots,paymentStatuses,onBack,onEdit,onAddOrder,onRepeatOrder,onPayment,onReturn,onReverseEntry,onArchive,onAddNote}:{business:Business;customer:Customer;balance:CustomerBalance;orders:Order[];entries:LedgerEntry[];notes:BusinessData['notes'];slots:Map<string,Slot>;paymentStatuses:Map<string,OrderPaymentStatus>;onBack:()=>void;onEdit:()=>void;onAddOrder:()=>void;onRepeatOrder:()=>void;onPayment:(orderId:string|null)=>void;onReturn:()=>void;onReverseEntry:(id:string)=>void;onArchive:()=>void;onAddNote:(note:string)=>void}){
  const [note,setNote]=useState('')
  const [showAll,setShowAll]=useState(false)
  const reversed=new Set(entries.map(e=>e.reversal_of_id).filter(Boolean))
  const events=[...orders.map(order=>({kind:'order' as const,id:order.id,date:order.delivered_at?.slice(0,10)??order.service_date,order})),...entries.map(entry=>({kind:'ledger' as const,id:entry.id,date:entry.occurred_on,entry})),...notes.map(item=>({kind:'note' as const,id:item.id,date:item.created_at.slice(0,10),note:item}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,showAll?undefined:40)
  const upcoming=orders.filter(order=>order.status==='scheduled'&&order.service_date>=todayForZone(business.time_zone)).sort((a,b)=>a.service_date.localeCompare(b.service_date))
  const total=balance.total_owed_minor
  return <><div className="back-row"><button className="quiet-button" onClick={onBack}><ArrowLeft size={15}/> Customers</button></div><div className="customer-detail-heading"><div className="detail-person"><span className="customer-avatar detail-avatar">{initials(customer.full_name)}</span><div><span className="eyebrow">CUSTOMER ACCOUNT</span><h1>{customer.full_name}</h1><p>{[customer.phone_e164,customer.flat_number,customer.building,customer.address_text].filter(Boolean).join(' · ')||'No phone or address saved yet'}</p></div></div><div className="heading-actions"><button className="secondary-button" onClick={onEdit}><Edit3 size={15}/> Edit details</button><button className="secondary-button" onClick={()=>{if(window.confirm(`Archive ${customer.full_name}? Their history and balance will stay in the account.`))onArchive()}}>{customer.status==='archived'?'Archived':'Archive customer'}</button></div></div>
    <div className="detail-metrics"><article className="detail-metric balance-metric"><span className="eyebrow">TOTAL OWED</span><strong className={total<0?'credit':''}>{formatMoney(Math.abs(total),business.currency_code)}</strong><small>{total<0?'Customer credit':total===0?'All caught up':'Across delivered orders and payments'}</small></article><article className="detail-metric"><span className="eyebrow">BOOKED AHEAD</span><strong>{balance.booked_order_count}</strong><small>{formatMoney(balance.booked_minor,business.currency_code)} scheduled</small></article><article className="detail-metric"><span className="eyebrow">OLDEST UNPAID</span><strong className="metric-date">{balance.oldest_unpaid_on?plainDateLabel(balance.oldest_unpaid_on,{day:'numeric',month:'short',year:'numeric'}):'—'}</strong><small>{balance.oldest_unpaid_on?'From the oldest open order':'No unpaid order'}</small></article></div>
    <div className="detail-action-row"><button className="primary-button" onClick={onAddOrder}><Plus size={16}/> Add an order</button><button className="secondary-button" onClick={onRepeatOrder}><ArrowRight size={15}/> Repeat last order</button><button className="secondary-button" onClick={()=>onPayment(null)}><Wallet size={16}/> Record payment</button><button className="secondary-button" onClick={onReturn}><CreditCard size={15}/> Record return</button></div>
    <div className="detail-columns"><section className="content-card detail-card"><div className="card-heading"><div><span className="eyebrow">WHAT’S NEXT</span><h2>Booked ahead</h2></div><button className="quiet-button" onClick={onAddOrder}><Plus size={15}/> Add</button></div>{upcoming.length?upcoming.slice(0,6).map(order=><div className="upcoming-order" key={order.id}><span className="upcoming-date">{plainDateLabel(order.service_date,{weekday:'short',day:'numeric',month:'short'})}</span><span className="upcoming-description">{order.description||'Order'}{order.slot_id&&slots.get(order.slot_id)&&<small>{slots.get(order.slot_id)?.name}</small>}</span><span className="order-amount">{formatMoney(order.amount_minor,business.currency_code)}</span></div>):<div className="mini-empty">No future orders booked.</div>}</section><section className="content-card detail-card"><div className="card-heading"><div><span className="eyebrow">A NOTE TO REMEMBER</span><h2>Customer notes</h2></div><FileText size={17} className="subtle-icon"/></div><form className="note-form" onSubmit={event=>{event.preventDefault();if(note.trim()){onAddNote(note.trim());setNote('')}}}><textarea rows={2} maxLength={4000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Delivery details, preferences, or anything helpful…"/><button className="secondary-button" type="submit" disabled={!note.trim()}><Plus size={14}/> Add note</button></form>{notes.slice(0,3).map(item=><div className="saved-note" key={item.id}><p>{item.note}</p><small>{plainDateLabel(item.created_at.slice(0,10),{day:'numeric',month:'short',year:'numeric'})}</small></div>)}</section></div>
    <section className="content-card timeline-card"><div className="card-heading"><div><span className="eyebrow">EVERYTHING IN ONE PLACE</span><h2>Orders and payments</h2></div><span className="timeline-balance">Balance {formatMoney(total,business.currency_code)}</span></div>{events.length?events.map(event=>event.kind==='order'?<div className="timeline-row" key={`o-${event.id}`}><span className={`timeline-icon ${event.order.status==='delivered'?'sage':'peach'}`}>{event.order.status==='delivered'?<Check size={15}/>:<Cookie size={15}/>}</span><div className="timeline-main"><strong>{event.order.status==='cancelled'?'Cancelled order':event.order.status==='delivered'?'Delivered order':'Scheduled order'}{event.order.order_kind==='bulk'?' · Bulk':''}</strong><small>{plainDateLabel(event.date,{day:'numeric',month:'short',year:'numeric'})} · {event.order.description||'Order'} · Qty {event.order.quantity}{event.order.slot_id&&slots.get(event.order.slot_id)?` · ${slots.get(event.order.slot_id)?.name}`:''}</small></div><div className="timeline-amount"><strong>{formatMoney(event.order.amount_minor,business.currency_code)}</strong>{event.order.status==='delivered'&&paymentStatuses.get(event.order.id)&&<small>{paymentStatuses.get(event.order.id)?.payment_status.replace('_',' ')}</small>}</div></div>:event.kind==='ledger'?<div className="timeline-row" key={`l-${event.id}`}><span className={`timeline-icon ${event.entry.entry_kind==='received'?'sage':'peach'}`}>{event.entry.entry_kind==='received'?<ArrowLeft size={15}/>:<ArrowRight size={15}/>}</span><div className="timeline-main"><strong>{event.entry.entry_kind==='received'?'Payment received':'Money returned'}{event.entry.reversal_of_id?' · Reversal':''}</strong><small>{plainDateLabel(event.date,{day:'numeric',month:'short',year:'numeric'})}{event.entry.payment_method?` · ${event.entry.payment_method.replace('_',' ')}`:''}{event.entry.reference_note?` · ${event.entry.reference_note}`:''}{event.entry.tagged_order_id?' · Tagged to an order':''}</small></div><div className="timeline-amount"><strong>{event.entry.entry_kind==='received'?'+':'−'}{formatMoney(event.entry.amount_minor,business.currency_code)}</strong>{!reversed.has(event.entry.id)&&<button className="text-button" onClick={()=>{if(window.confirm('Record a reversing entry? This adds a new ledger line and cannot be deleted.'))onReverseEntry(event.entry.id)}}>Reverse</button>}</div></div>:<div className="timeline-row" key={`n-${event.id}`}><span className="timeline-icon lilac"><FileText size={14}/></span><div className="timeline-main"><strong>Customer note</strong><small>{plainDateLabel(event.date,{day:'numeric',month:'short',year:'numeric'})} · {event.note.note}</small></div></div>):<div className="mini-empty">No orders or payments have been recorded yet.</div>}{events.length>40&&<button className="text-button" onClick={()=>setShowAll(!showAll)}>{showAll?'Show less':'Show all history'}</button>}</section></>
}

export function RemindersScreen({business,balances,events,onWhatsApp,onCopy,onUndo}:{business:Business;balances:CustomerBalance[];events:ReminderEvent[];onWhatsApp:(customer:CustomerBalance)=>Promise<void>;onCopy:(customer:CustomerBalance)=>Promise<void>;onUndo:(id:string)=>void}){
  const [kind,setKind]=useState<'weekly'|'monthly'>('weekly')
  const today=todayForZone(business.time_zone)
  const due=balances.filter(customer=>customer.status==='active'&&customer.total_owed_minor>0).sort((a,b)=>b.total_owed_minor-a.total_owed_minor)
  const latestByCustomer=new Map<string,ReminderEvent>()
  for(const event of events.filter(item=>item.reminder_date===today&&item.action!=='undone')){
    const undone=events.some(item=>item.action==='undone'&&item.undo_of_id===event.id)
    if(!undone&&!latestByCustomer.has(event.customer_id))latestByCustomer.set(event.customer_id,event)
  }
  const dayName=business.reminder_weekday===null?'not set':['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][business.reminder_weekday]
   return <><div className="page-heading"><div><span className="eyebrow">A GENTLE FOLLOW-UP</span><h1>Reminders<span className="heading-period">.</span></h1><p>Review the message, then send it yourself in WhatsApp.</p></div><span className="reminder-count">{due.length} customers owe</span></div><div className="reminder-tabs"><button className={kind==='weekly'?'selected':''} onClick={()=>setKind('weekly')}>Weekly list <span>{due.length}</span></button><button className={kind==='monthly'?'selected':''} onClick={()=>setKind('monthly')}>Monthly list <span>{due.length}</span></button></div><div className="reminder-context"><Sparkles size={16}/><span>{kind==='weekly'?`Weekly reminder day: ${dayName}.`:`Monthly reminder day: ${business.reminder_day??'not set'}.`} Everyone with an amount owed appears here.</span><span className="context-small">No one is automatically messaged.</span></div><section className="content-card reminders-card"><div className="reminder-head"><span>CUSTOMER</span><span>OWED SINCE</span><span>LAST REMINDED</span><span>AMOUNT OWED</span><span>ACTION</span></div>{due.length?due.map(customer=>{const event=latestByCustomer.get(customer.customer_id);return <div className="reminder-row" key={customer.customer_id}><span className="customer-cell"><span className="customer-avatar">{initials(customer.full_name)}</span><span><strong>{customer.full_name}</strong><small>{customer.phone_e164||'No phone saved'}</small></span></span><span>{customer.oldest_unpaid_on?plainDateLabel(customer.oldest_unpaid_on,{day:'numeric',month:'short',year:'numeric'}):'—'}</span><span>{event?'Today':'Not reminded'}</span><strong>{formatMoney(customer.total_owed_minor,business.currency_code)}</strong><span className="reminder-actions">{event?<button className="quiet-button" onClick={()=>onUndo(event.id)}>Undo</button>:<><button className="whatsapp-button" disabled={!customer.phone_e164} onClick={()=>void onWhatsApp(customer)}><MessageCircle size={14}/> WhatsApp</button><button className="icon-button" title="Copy message" aria-label={`Copy reminder for ${customer.full_name}`} onClick={()=>void onCopy(customer)}><FileText size={15}/></button></>}</span></div>}):<div className="empty-state"><span className="empty-icon"><Check size={21}/></span><strong>All caught up.</strong><p>Customers with an amount owed will show up here.</p></div>}</section></>
}

export function SettingsScreen({business,slots,closures,onSaveBusiness,onSaveSlot,onAddClosure,onRemoveClosure,onExportCustomers,onExportOrders,onExportPayments}:{business:Business;slots:Slot[];closures:ClosureRule[];onSaveBusiness:(values:Omit<Business,'id'>&{id?:string})=>Promise<void>;onSaveSlot:(slot:Partial<Slot>&{name:string})=>Promise<void>;onAddClosure:()=>void;onRemoveClosure:(rule:ClosureRule)=>void;onExportCustomers:()=>void;onExportOrders:()=>void;onExportPayments:()=>void}){
  const [name,setName]=useState(business.name)
  const [countryCode,setCountryCode]=useState(business.country_code)
  const [currency,setCurrency]=useState(business.currency_code)
  const [timeZone,setTimeZone]=useState(business.time_zone)
  const [weekly,setWeekly]=useState(business.reminder_weekday===null?'':String(business.reminder_weekday))
  const [monthly,setMonthly]=useState(business.reminder_day===null?'':String(business.reminder_day))
  const [reminderTime,setReminderTime]=useState(business.reminder_time?.slice(0,5)??'')
  const [template,setTemplate]=useState(business.reminder_template??'Hi {customer_name}, your pending amount at {business_name} is {total_owed}. Please pay when convenient. Thank you!')
  const [terminology,setTerminology]=useState(business.terminology?.order??'order')
  const [saving,setSaving]=useState(false)
  const [slotName,setSlotName]=useState('')
  const [slotTime,setSlotTime]=useState('')
  async function saveBusiness(event:FormEvent){event.preventDefault();setSaving(true);try{await onSaveBusiness({name,country_code:countryCode,currency_code:currency,time_zone:timeZone,reminder_weekday:weekly===''?null:Number(weekly),reminder_day:monthly===''?null:Number(monthly),reminder_time:reminderTime||null,reminder_template:template,terminology:{...business.terminology,order:terminology}})}finally{setSaving(false)}}
  async function createSlot(event:FormEvent){event.preventDefault();if(!slotName.trim())return;setSaving(true);try{await onSaveSlot({name:slotName.trim(),starts_at:slotTime||null,ends_at:null,sort_order:slots.length,is_active:true});setSlotName('');setSlotTime('')}finally{setSaving(false)}}
  async function applyPreset(kind:'tiffin'|'daily'|'by_day'){setSaving(true);try{const layouts=kind==='tiffin'?[['Breakfast','08:00'],['Lunch','12:00'],['Dinner','19:00']]:kind==='daily'?[['Morning','08:00'],['Afternoon','13:00'],['Evening','19:00']]:[];for(const [i,[slotName,start]] of layouts.entries()){if(!slots.some(slot=>slot.name.toLowerCase()===slotName.toLowerCase()))await onSaveSlot({name:slotName,starts_at:start,ends_at:null,sort_order:i,is_active:true})}setTerminology(kind==='tiffin'?'tiffin':kind==='daily'?'delivery':'order')}finally{setSaving(false)}}
  return <><div className="page-heading"><div><span className="eyebrow">YOUR BUSINESS, YOUR WAY</span><h1>Settings<span className="heading-period">.</span></h1><p>Manage your business, delivery schedule and reminder wording.</p></div></div><div className="settings-layout"><div className="settings-main"><section className="content-card settings-card"><div className="settings-card-heading"><span className="settings-icon"><Settings size={17}/></span><div><h2>Business details</h2><p>These details set the calendar and money display.</p></div></div><form className="settings-form" onSubmit={saveBusiness}><div className="form-grid"><label>Business name<input required maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></label><label>Default phone country code<input required maxLength={4} value={countryCode} onChange={e=>setCountryCode(e.target.value.replace(/\D/g,''))}/></label><label>Currency code<input required maxLength={3} value={currency} onChange={e=>setCurrency(e.target.value.toUpperCase())}/></label><label>Business timezone<input required value={timeZone} onChange={e=>setTimeZone(e.target.value)}/></label><label>Display term for “order”<input value={terminology} onChange={e=>setTerminology(e.target.value)}/></label></div><button className="primary-button" type="submit" disabled={saving}>{saving?'Saving…':'Save business details'}</button></form><p className="settings-hint">Country, currency and timezone lock after business activity so existing records keep their meaning.</p></section>
    <section className="content-card settings-card"><div className="settings-card-heading"><span className="settings-icon peach"><Clock3 size={17}/></span><div><h2>Weekly and monthly reminders</h2><p>Choose the days your lists are most useful.</p></div></div><form className="settings-form" onSubmit={saveBusiness}><div className="form-grid"><label>Weekly list day<select value={weekly} onChange={e=>setWeekly(e.target.value)}><option value="">Not set</option>{['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((day,i)=><option value={i} key={day}>{day}</option>)}</select></label><label>Monthly list day<select value={monthly} onChange={e=>setMonthly(e.target.value)}><option value="">Not set</option>{Array.from({length:31},(_,i)=><option value={i+1} key={i}>{i+1}</option>)}</select></label><label>Usual reminder time<input type="time" value={reminderTime} onChange={e=>setReminderTime(e.target.value)}/></label><label>Message template<textarea rows={4} maxLength={2000} value={template} onChange={e=>setTemplate(e.target.value)}/><small>Placeholders: {'{customer_name}'}, {'{total_owed}'}, {'{business_name}'}, {'{date_owed_since}'}</small></label></div><button className="primary-button" type="submit" disabled={saving}>Save reminder settings</button></form></section>
    <section className="content-card settings-card"><div className="settings-card-heading"><span className="settings-icon sage"><CalendarDays size={17}/></span><div><h2>Delivery slots</h2><p>Rename and reorder slots, or archive one from future orders.</p></div></div><div className="slot-settings-list">{slots.map(slot=><SlotSettingsRow slot={slot} key={slot.id} busy={saving} onSave={onSaveSlot}/>)}</div><form className="slot-add-row" onSubmit={createSlot}><input value={slotName} onChange={e=>setSlotName(e.target.value)} placeholder="New slot name" maxLength={80}/><input type="time" value={slotTime} onChange={e=>setSlotTime(e.target.value)} aria-label="Slot start time"/><button className="secondary-button" type="submit" disabled={saving||!slotName.trim()}><Plus size={15}/> Add slot</button></form></section>
    <section className="content-card settings-card"><div className="settings-card-heading"><span className="settings-icon lilac"><SlidersHorizontal size={17}/></span><div><h2>Closures and exceptions</h2><p>Close a date range, weekday or monthly pattern; add an open exception when needed.</p></div><button className="secondary-button settings-heading-action" onClick={onAddClosure}><Plus size={15}/> Add closure</button></div>{closures.length?closures.map(rule=><div className="closure-row" key={rule.id}><span className={`closure-action-mark ${rule.action==='open_exception'?'open':''}`}>{rule.action==='closed'?'–':'+'}</span><span><strong>{closureLabel(rule)}</strong><small>{rule.slot_id?slots.find(slot=>slot.id===rule.slot_id)?.name??'Archived slot':'All slots'}{rule.reason?` · ${rule.reason}`:''}</small></span><button className="icon-button" aria-label="Remove closure" onClick={()=>{if(window.confirm('Remove this closure rule? Existing orders will stay as they are.'))onRemoveClosure(rule)}}><Trash2 size={15}/></button></div>):<div className="settings-empty">No closures configured yet.</div>}</section></div>
    <aside className="settings-side"><section className="content-card settings-card"><div className="settings-card-heading"><span className="settings-icon peach"><Sparkles size={17}/></span><div><h2>Start with a preset</h2><p>Presets add editable slots and terminology.</p></div></div><div className="preset-list"><button onClick={()=>void applyPreset('tiffin')} disabled={saving}><span>🍱</span><span><strong>Tiffin or home kitchen</strong><small>Breakfast, lunch and dinner</small></span><ArrowRight size={15}/></button><button onClick={()=>void applyPreset('daily')} disabled={saving}><span>🌤</span><span><strong>Daily delivery</strong><small>Morning, afternoon and evening</small></span><ArrowRight size={15}/></button><button onClick={()=>void applyPreset('by_day')} disabled={saving}><span>▦</span><span><strong>Orders by day only</strong><small>No delivery slots</small></span><ArrowRight size={15}/></button></div></section><section className="content-card settings-card export-card"><div className="settings-card-heading"><span className="settings-icon sage"><Download size={17}/></span><div><h2>Take your data with you</h2><p>Download CSV copies for your records.</p></div></div><button className="export-row" onClick={onExportCustomers}>Customers <Download size={14}/></button><button className="export-row" onClick={onExportOrders}>Orders <Download size={14}/></button><button className="export-row" onClick={onExportPayments}>Payments <Download size={14}/></button><p className="settings-hint">Exports are created in this browser; your data is not sent elsewhere.</p></section><div className="privacy-note"><CircleHelp size={16}/><p>Only invited business owners can access this workspace. Financial entries are append-only and corrections create a reversal.</p></div></aside></div></>
}

function SlotSettingsRow({slot,busy,onSave}:{slot:Slot;busy:boolean;onSave:(slot:Partial<Slot>&{name:string})=>Promise<void>}){
  const [name,setName]=useState(slot.name)
  const [start,setStart]=useState(slot.starts_at?.slice(0,5)??'')
  const [active,setActive]=useState(slot.is_active)
  async function submit(event:FormEvent){event.preventDefault();await onSave({id:slot.id,name,starts_at:start||null,ends_at:slot.ends_at,sort_order:slot.sort_order,is_active:active})}
  return <form className={`slot-settings-row ${!active?'archived':''}`} onSubmit={submit}><input value={name} onChange={e=>setName(e.target.value)} aria-label="Slot name" maxLength={80}/><input type="time" value={start} onChange={e=>setStart(e.target.value)} aria-label="Slot time"/><label className="toggle-label"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/><span>{active?'Active':'Archived'}</span></label><button className="icon-button" type="submit" disabled={busy||!name.trim()||name===slot.name&&start===(slot.starts_at?.slice(0,5)??'')&&active===slot.is_active} aria-label={`Save ${slot.name}`}><Check size={16}/></button></form>
}

export function closureLabel(rule:ClosureRule){
  if(rule.rule_type==='exception')return `Open exception · ${rule.starts_on?plainDateLabel(rule.starts_on,{day:'numeric',month:'short',year:'numeric'}):''}`
  if(rule.rule_type==='date_range')return `Closed · ${rule.starts_on?plainDateLabel(rule.starts_on,{day:'numeric',month:'short'}):''}–${rule.ends_on?plainDateLabel(rule.ends_on,{day:'numeric',month:'short',year:'numeric'}):''}`
  if(rule.rule_type==='daily')return `Every day${rule.starts_on?` · ${rule.starts_on} to ${rule.ends_on}`:''}`
  if(rule.rule_type==='weekday')return `Every ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][rule.weekday??0]}`
  if(rule.rule_type==='monthly_date')return `Monthly · day ${rule.month_day}`
  return `Monthly · ${ordinal(rule.week_of_month??1)} ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][rule.weekday??0]}`
}
function ordinal(value:number){return value===-1?'last':`${value}${value===1?'st':value===2?'nd':value===3?'rd':'th'}`}
function initials(name:string){return name.trim().split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase()}
